// Score each client on "opportunity to act now"
// Deterministic scoring so it's cheap and explainable - no LLM call needed here.

const today = new Date();

function daysUntil(dateStr) {
  const d = new Date(dateStr);
  return Math.ceil((d - today) / (1000 * 60 * 60 * 24));
}

return items.map(item => {
  const c = item.json;

  let score = 0;
  const reasons = [];

  // 1. Concentration risk
  const conc = parseFloat(c.top_holding_pct);
  if (conc >= 60) { score += 30; reasons.push(`High concentration risk: ${conc}% in a single holding`); }
  else if (conc >= 40) { score += 15; reasons.push(`Moderate concentration: ${conc}% in top holding`); }

  // 2. FD maturity within next 30 days = idle cash opportunity
  const daysToMaturity = daysUntil(c.fd_maturity_date);
  if (daysToMaturity >= 0 && daysToMaturity <= 30) {
    score += 25;
    reasons.push(`FD maturing in ${daysToMaturity} days - reinvestment conversation needed`);
  }

  // 3. Underperformance vs benchmark
  const gap = parseFloat(c.benchmark_return_1y_pct) - parseFloat(c.portfolio_return_1y_pct);
  if (gap >= 5) { score += 25; reasons.push(`Underperforming benchmark by ${gap.toFixed(1)}%`); }
  else if (gap >= 2) { score += 10; reasons.push(`Slightly trailing benchmark by ${gap.toFixed(1)}%`); }

  // 4. Unused PMS/AIF eligibility
  if (c.pms_aif_eligible === 'TRUE' && c.pms_aif_invested === 'FALSE') {
    score += 15;
    reasons.push('Eligible for PMS/AIF but not yet invested');
  }

  // 5. Stale relationship
  const daysSinceContact = parseInt(c.last_contact_days_ago, 10);
  if (daysSinceContact >= 90) { score += 15; reasons.push(`No contact in ${daysSinceContact} days`); }
  else if (daysSinceContact >= 60) { score += 8; reasons.push(`Contact getting stale (${daysSinceContact} days)`); }

  return {
    json: {
      client_id: c.client_id,
      client_name: c.client_name,
      portfolio_value_inr: c.portfolio_value_inr,
      opportunity_score: score,
      reasons
    }
  };
});

// Sort descending by score, keep only the top 5 - this is the deliberate
// design choice: RMs don't need talking points for every client, only
// the ones worth calling today.
return items
  .sort((a, b) => b.json.opportunity_score - a.json.opportunity_score)
  .slice(0, 5);

const clients = $input.first().json.data;

// Format raw rupee numbers into readable Cr/Lakh
function formatINR(value) {
  const num = parseFloat(value);
  if (num >= 10000000) return `₹${(num / 10000000).toFixed(2)} Cr`;
  if (num >= 100000) return `₹${(num / 100000).toFixed(1)} L`;
  return `₹${num.toLocaleString('en-IN')}`;
}

// Turn a raw score into a decision-ready priority label
function getPriority(score) {
  if (score >= 90) return { label: '🔴 Urgent', tier: 'Urgent' };
  if (score >= 60) return { label: '🟡 Monitor', tier: 'Monitor' };
  return { label: '🟢 Stable', tier: 'Stable' };
}

// Strip markdown bold/asterisks since this isn't rendered anywhere
function cleanText(text) {
  return (text || '').replace(/\*\*/g, '').trim();
}

// Structured version — clean columns for the Table view
const structured = clients.map((c, i) => {
  const priority = getPriority(c.opportunity_score);
  return {
    rank: i + 1,
    priority: priority.label,
    client_name: c.client_name,
    client_id: c.client_id,
    portfolio_value: formatINR(c.portfolio_value_inr),
    opportunity_score: c.opportunity_score,
    top_reason: c.reasons[0],
    all_reasons: c.reasons.join(' | '),
    talking_points: cleanText(c.talking_points)
  };
});

// Summary line — total AUM at risk, FD maturities, urgent count
const totalAUM = clients.reduce((sum, c) => sum + parseFloat(c.portfolio_value_inr), 0);
const fdCount = clients.filter(c => c.reasons.some(r => r.toLowerCase().includes('fd maturing'))).length;
const urgentCount = clients.filter(c => c.opportunity_score >= 90).length;

const summaryLine =
  `${clients.length} clients flagged today | ${formatINR(totalAUM)} in AUM under review | ` +
  `${urgentCount} urgent | ${fdCount} FD${fdCount === 1 ? '' : 's'} maturing this window`;

// Formatted text version — headers, dividers, priority tags
const divider = '─'.repeat(48);

const formattedSections = clients.map((c, i) => {
  const priority = getPriority(c.opportunity_score);
  const reasonLines = c.reasons.map(r => `  • ${r}`).join('\n');
  return [
    divider,
    `#${i + 1}  ${priority.label}   ${c.client_name}   (${formatINR(c.portfolio_value_inr)} | Score: ${c.opportunity_score})`,
    divider,
    `Why call today:`,
    reasonLines,
    ``,
    `Talking points:`,
    cleanText(c.talking_points),
    ``
  ].join('\n');
});

const formatted_briefing =
  `DAILY RM BRIEFING — ${new Date().toDateString()}\n` +
  `${summaryLine}\n\n` +
  formattedSections.join('\n');

return [{
  json: {
    summary: summaryLine,
    clients: structured,
    formatted_briefing
  }
}];

// The input to this node is the Groq HTTP response for the current client.
// Pull the generated talking points, then re-attach the original client fields
// from the loop so downstream aggregation has everything it needs.
const response = $input.first().json;
const talkingPoints = response?.choices?.[0]?.message?.content || '';
const client = $('Loop Over Top Clients').item.json;

return [{
  json: {
    client_id: client.client_id,
    client_name: client.client_name,
    portfolio_value_inr: client.portfolio_value_inr,
    opportunity_score: client.opportunity_score,
    reasons: client.reasons,
    talking_points: talkingPoints
  }
}];

const { summary, clients } = $input.first().json;

const rows = clients.map(c => `
  <tr>
    <td>${c.rank}</td>
    <td>${c.priority}</td>
    <td>${c.client_name}</td>
    <td>${c.portfolio_value}</td>
    <td>${c.opportunity_score}</td>
    <td>${c.top_reason}</td>
  </tr>
`).join('');

const detailSections = clients.map(c => `
  <div class="client-block">
    <h3>#${c.rank} ${c.priority} — ${c.client_name} (${c.portfolio_value})</h3>
    <p><strong>Why call today:</strong></p>
    <ul>${c.all_reasons.split(' | ').map(r => `<li>${r}</li>`).join('')}</ul>
    <p><strong>Talking points:</strong></p>
    <p>${c.talking_points.replace(/\n/g, '<br>')}</p>
  </div>
`).join('');

const html = `
<html>
<head>
<style>
  body { font-family: Arial, sans-serif; color: #222; padding: 20px; }
  h1 { color: #1a3c6e; margin-bottom: 4px; }
  .summary { background: #f0f4f8; padding: 12px; border-radius: 6px; margin-bottom: 20px; font-weight: bold; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 30px; }
  th, td { border: 1px solid #ccc; padding: 8px; text-align: left; font-size: 13px; }
  th { background: #1a3c6e; color: white; }
  .client-block { border-top: 2px solid #eee; padding-top: 12px; margin-bottom: 20px; page-break-inside: avoid; }
  h3 { color: #1a3c6e; }
  li { margin-bottom: 6px; }
</style>
</head>
<body>
  <h1>Daily RM Briefing</h1>
  <div class="summary">${summary}</div>
  <table>
    <tr><th>#</th><th>Priority</th><th>Client</th><th>AUM</th><th>Score</th><th>Top Reason</th></tr>
    ${rows}
  </table>
  <h2>Details</h2>
  ${detailSections}
</body>
</html>`;

return [{ json: { html } }];
